const n='# 📘 第12课：链表基础\n\n> **课程定位**：指针的实战 —— 理解链表结构，掌握基本操作\n\n---\n\n## 一、学习目标\n\n1. ✅ 理解链表的概念和优势\n2. ✅ 掌握链表节点的定义\n3. ✅ 熟练实现插入、删除、遍历操作\n4. ✅ 理解指针操作的本质\n\n---\n\n## 二、什么是链表？\n\n### 2.1 数组 vs 链表\n\n| 特性      | 数组          | 链表          |\n| --------- | ------------- | ------------- |\n| 内存      | 连续          | 分散          |\n| 访问      | O(1) 随机访问 | O(n) 顺序访问 |\n| 插入/删除 | O(n)          | O(1)          |\n| 大小      | 固定          | 动态          |\n\n### 2.2 链表的结构\n\n```\n[数据|指针] → [数据|指针] → [数据|指针] → NULL\n```\n\n每个节点包含：\n\n- **数据域**：存储数据\n- **指针域**：指向下一个节点\n\n---\n\n## 三、节点定义\n\n```cpp\nstruct Node {\n    int data;      // 数据域\n    Node* next;    // 指针域\n\n    // 构造函数\n    Node(int val) : data(val), next(nullptr) {}\n};\n```\n\n---\n\n## 四、基本操作\n\n### 4.1 创建链表\n\n```cpp\nNode* createList() {\n    Node* head = new Node(1);\n    head->next = new Node(2);\n    head->next->next = new Node(3);\n    return head;\n}\n```\n\n### 4.2 遍历链表\n\n```cpp\nvoid printList(Node* head) {\n    Node* cur = head;\n    while (cur != nullptr) {\n        cout << cur->data << " ";\n        cur = cur->next;\n    }\n    cout << endl;\n}\n```\n\n### 4.3 在头部插入\n\n```cpp\nNode* insertAtHead(Node* head, int val) {\n    Node* newNode = new Node(val);\n    newNode->next = head;\n    return newNode;\n}\n```\n\n### 4.4 在尾部插入\n\n```cpp\nvoid insertAtTail(Node* head, int val) {\n    Node* cur = head;\n    while (cur->next != nullptr) {\n        cur = cur->next;\n    }\n    cur->next = new Node(val);\n}\n```\n\n### 4.5 删除节点\n\n```cpp\nNode* deleteNode(Node* head, int val) {\n    // 删除头节点\n    if (head != nullptr && head->data == val) {\n        Node* temp = head;\n        head = head->next;\n        delete temp;\n        return head;\n    }\n\n    // 删除中间或尾部节点\n    Node* cur = head;\n    while (cur != nullptr && cur->next != nullptr) {\n        if (cur->next->data == val) {\n            Node* temp = cur->next;\n            cur->next = cur->next->next;\n            delete temp;\n            return head;\n        }\n        cur = cur->next;\n    }\n\n    return head;\n}\n```\n\n### 4.6 查找节点\n\n```cpp\nNode* search(Node* head, int val) {\n    Node* cur = head;\n    while (cur != nullptr) {\n        if (cur->data == val) return cur;\n        cur = cur->next;\n    }\n    return nullptr;\n}\n```\n\n---\n\n## 五、完整示例\n\n```cpp\n#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data;\n    Node* next;\n    Node(int val) : data(val), next(nullptr) {}\n};\n\nvoid printList(Node* head) {\n    while (head) {\n        cout << head->data << " -> ";\n        head = head->next;\n    }\n    cout << "NULL" << endl;\n}\n\nint main() {\n    // 创建链表：1 -> 2 -> 3\n    Node* head = new Node(1);\n    head->next = new Node(2);\n    head->next->next = new Node(3);\n\n    cout << "原链表：";\n    printList(head);\n\n    // 在头部插入 0\n    Node* newHead = new Node(0);\n    newHead->next = head;\n    head = newHead;\n\n    cout << "插入0后：";\n    printList(head);\n\n    // 删除节点 2\n    Node* cur = head;\n    while (cur->next && cur->next->data != 2) {\n        cur = cur->next;\n    }\n    if (cur->next) {\n        Node* temp = cur->next;\n        cur->next = cur->next->next;\n        delete temp;\n    }\n\n    cout << "删除2后：";\n    printList(head);\n\n    return 0;\n}\n```\n\n---\n\n## 六、带头节点的链表\n\n使用**哨兵节点**简化操作：\n\n```cpp\nNode* createWithDummy() {\n    Node* dummy = new Node(0);  // 哨兵节点\n    Node* cur = dummy;\n\n    for (int i = 1; i <= 3; i++) {\n        cur->next = new Node(i);\n        cur = cur->next;\n    }\n\n    return dummy;  // 返回哨兵节点\n}\n```\n\n---\n\n## 七、本课小结\n\n### 核心操作\n\n| 操作     | 时间复杂度 |\n| -------- | ---------- |\n| 头部插入 | O(1)       |\n| 尾部插入 | O(n)       |\n| 删除     | O(n)       |\n| 查找     | O(n)       |\n\n### 关键技巧\n\n- 哨兵节点简化边界处理\n- 删除时要保存前驱节点\n- 注意 nullptr 检查\n\n---\n\n**下节预告**：第13课 - 链表应用题！\n';export{n as default};
